  function readStorage(key){try{const rows=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(rows)?rows:[]}catch(error){console.warn(`Could not read ${key}.`,error);return[]}}
  function colour(value,fallback){return /^#[0-9a-f]{6}$/i.test(String(value||''))?value:fallback}
  function hash(value){let result=0;for(const char of String(value))result=((result<<5)-result+char.charCodeAt(0))|0;return Math.abs(result)}
  function createdKit(raw,a,b){return{pattern:raw?.pattern||'plain',primary:raw?.primary||a,secondary:raw?.secondary||b,shorts:raw?.shorts||b,socks:raw?.socks||a}}
  function generatedAppearance(seed){return{skinIndex:seed%8,hairIndex:(seed>>2)%7,hairStyle:(seed>>4)%8,faceIndex:(seed>>6)%12,eyeIndex:(seed>>8)%5,browIndex:(seed>>10)%5,beardStyle:(seed%5===0)?1+(seed%4):0,noseIndex:(seed>>12)%6,jawIndex:(seed>>14)%5,chinIndex:(seed>>16)%4,earIndex:(seed>>18)%4,bodyIndex:(seed>>20)%5,hairlineIndex:(seed>>22)%5,heightIndex:(seed>>24)%7,sleeveIndex:(seed>>26)%4}}
  function generatedSquad(team){const names=['Harper','Wright','Ellison','Boyd','Nakamura','Okafor','Da Costa','Lindqvist','Mensah','Novak','Reyes','Morgan','Silva','Barker','Hughes','Bennett','Taylor','Clarke','Roberts','Mason','Walker','White','Jackson'];const pos=['GK','GK','GK','RB','CB','CB','LB','CB','RWB','LWB','CDM','CM','CM','CAM','RM','LM','RW','LW','ST','ST','CF','ST','ST'];return pos.map((position,i)=>{const overall=Math.max(42,Math.min(90,(team.ratings?.overall||62)+(i<11?1:-(i-9))));const role=position==='GK'?'gk':['RB','CB','LB','RWB','LWB'].includes(position)?'def':['ST','CF'].includes(position)?'fwd':'mid';const seed=hash(`${team.id}-${i}`);const attrs={pace:overall,accel:overall,control:overall,pass:overall,shoot:Math.max(30,overall+(role==='fwd'?6:-4)),defend:Math.max(30,overall+(role==='def'?6:-8)),awareness:overall,strength:overall,heading:overall,jumping:overall,balance:overall,agility:overall,technique:overall,aggression:overall,keeper:role==='gk'?overall:25};return{id:`${team.id}-created-${i}`,name:names[i],position,role,overall,number:i===0?1:i+2,attrs,appearance:generatedAppearance(seed),age:20+(seed%14),seasonApps:0,seasonGoals:0}})}
  function loadCreatedTeams(){const stadiumRows=readStorage('footballLegacyCreatedStadiumsV1'),stadiumMap=new Map(stadiumRows.map(row=>[row.id,row]));return readStorage('footballLegacyCreatedClubsV1').map((club,index)=>{const primary=colour(club.colours?.primary,'#173a63'),secondary=colour(club.colours?.secondary,'#f4ead8'),stadium=stadiumMap.get(club.stadiumId),overall=Number(club.ratings?.overall)||62;const team={id:club.id||`created-club-${index+1}`,name:club.name||`Created Club ${index+1}`,shortName:club.shortName||club.abbreviation||'CC',abbreviation:club.abbreviation||String(club.name||'CC').slice(0,3).toUpperCase(),source:'created',countryId:'england',divisionId:'created',rating:overall,ratings:{overall,attack:Number(club.ratings?.attack)||overall,midfield:Number(club.ratings?.midfield)||overall,defence:Number(club.ratings?.defence)||overall},colours:{primary,secondary,accent:colour(club.colours?.accent,'#e87824')},kits:{home:createdKit(club.kits?.home,primary,secondary),away:createdKit(club.kits?.away,secondary,primary),third:createdKit(club.kits?.gk,'#1b2430',primary)},formation:club.teamSetup?.formation||'4-4-2',founded:Number(club.founded)||2026,reputation:club.reputation||'Created Club',stadiumId:club.stadiumId||`created-stadium-${club.id}`,stadium:stadium?.name||'Created Club Ground',stadiumRecord:stadium||null,squadId:`created-squad-${club.id}`,playerIds:club.squad?.playerIds||[]};team.squad=generatedSquad(team);return team})}
  function getLeagueTeams(leagueId){return leagueId==='created'?loadCreatedTeams():(TEAMS[leagueId]||[])}
  function getTeam(leagueId,teamId){return getLeagueTeams(leagueId).find(team=>team.id===teamId)||null}
  function getSquad(leagueId,teamId){return getTeam(leagueId,teamId)?.squad||[]}
